import{_ as l,l as o,o as e,c as s,v as t,p as n,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"激光气体与寿命","description":"","frontmatter":{"title":"激光气体与寿命","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/laser-gas-lifetime.md","filePath":"litho/laser-gas-lifetime.md","lastUpdated":1789023840000}'),_={name:"litho/laser-gas-lifetime.md"};function E(c,a,m,f,u,A){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="激光气体与寿命" tabindex="-1">激光气体与寿命 <a class="header-anchor" href="#激光气体与寿命" aria-label="Permalink to &quot;激光气体与寿命&quot;">​</a></h1><div class="epigraph"><p>氟在放电里干活，也在腐蚀电极和窗口。气体寿命是功率、带宽和成本的同一条曲线，不是耗材小票。</p><footer>—— 对照准分子气体补给 / 腔寿命的公开运行描述</footer></div><p><a href="/litho/pulse-energy-rep-rate">上一课</a>要稳定的 \\(E_p\\)。缺口是工作气体会脏、会耗：氟消耗、产物污染、窗口透过率掉。本课钉气体与腔寿命，不写 EUV 锡。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>放电把 F₂ 变成产物、溅射电极、在窗口上镀一层脏。同一套压窄设定下，\\(E_p\\) 慢慢掉、带宽慢慢漂，看起来像剂量漂移。只调剂量闭环、不换气，会把耗材问题写成胶批次。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>运行：定期注气、循环过滤、按脉冲计数或能量积分触发换气/换窗。寿命指标用「可维持规格的脉冲数」而不是日历天。窗口与腔镜是另一条资本寿命，与气体罐分开记账。</p>',7)),(e(),n(h,null,{default:r(()=>[p(i,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20GAS%5B%22Ar%2FF2%20%E6%B7%B7%E5%90%88%22%5D%20--%3E%20DIS%5B%22%E6%94%BE%E7%94%B5%22%5D%0A%20%20DIS%20--%3E%20CONT%5B%22%E4%BA%A7%E7%89%A9%20%2F%20%E7%AA%97%E5%8F%A3%E6%B1%A1%E6%9F%93%22%5D%0A%20%20CONT%20--%3E%20EP%5B%22Ep%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20GAS%20--%3E%20REFILL%5B%22%E6%B3%A8%E6%B0%94%E5%91%A8%E6%9C%9F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">过量注氟可以提高短期能量，加快腐蚀。寿命曲线是化学与功率的权衡，不是越大越狠越好。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>准分子形成需要足够 F₂；过多 F₂ 吸收 193 nm、腐蚀加剧。金属氟化物沉积改腔 Q 值与透过。压窄光栅对污染同样敏感，带宽规格会先于肉眼「变暗」而失守。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课离开激光头，进照明均光。气体课不解释复眼透镜。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>气体与窗口寿命表现为 \\(E_p\\) 与带宽漂移。</li><li>注气周期是工艺参数，要进 SPC。</li><li>出处：准分子运行通识；脉冲能量课。</li></ul>',7))])}const S=l(_,[["render",E]]);export{T as __pageData,S as default};
